"""Build a standalone, capture-ready 16:9 visual deck from narration-mapped slides."""
from pathlib import Path
import json
P=Path(__file__).resolve().parent
slides=json.loads((P/'slides/slides.json').read_text())
template=r'''<!doctype html><html lang="en"><meta charset="utf-8"><title>Freelance Engineering · Hammad</title><style>
*{box-sizing:border-box}body{margin:0;background:#06091b;color:#f2f5ff;font-family:Arial,Helvetica,sans-serif;overflow:hidden}#stage{width:1920px;height:1080px;position:absolute;transform-origin:top left;background:radial-gradient(ellipse at 12% 0%,#353194 0,transparent 54%),radial-gradient(ellipse at 100% 100%,#144979 0,transparent 55%),#0a102b;padding:64px}main{height:100%;border:1px solid #6972b044;border-radius:30px;background:linear-gradient(135deg,#0a0d20f5,#070b19fa);padding:64px 72px;box-shadow:0 30px 100px #0008;position:relative}.eyebrow{font-size:21px;letter-spacing:4px;text-transform:uppercase;color:#a7aaf7;display:flex;justify-content:space-between}h1{font-size:66px;line-height:1.08;letter-spacing:-2px;max-width:1470px;margin:40px 0 55px}#content{display:grid;gap:26px;height:470px;align-content:center}.card{background:linear-gradient(145deg,#191d36,#101426);border:1px solid #585f8d55;border-radius:20px;padding:38px;min-height:190px;display:flex;flex-direction:column;justify-content:center;position:relative}.card .num{font-size:21px;letter-spacing:3px;color:#9998ed;margin-bottom:24px}.card .label{font-size:37px;line-height:1.28;letter-spacing:-.4px}.compare{grid-template-columns:1fr 1fr}.compare .card{min-height:350px;border-top:4px solid #8581ff}.compare .card:nth-child(2){border-top-color:#5bd4d1}.cards{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:repeat(3,1fr)}.grid .card{min-height:135px;padding:24px 30px}.grid .label{font-size:29px}.grid .num{margin-bottom:10px;font-size:16px}.flow{grid-template-columns:repeat(3,1fr);gap:58px!important}.flow .card{min-height:280px}.flow .card:not(:last-child):after{content:'→';position:absolute;right:-46px;top:44%;font-size:36px;color:#9998ed}.timeline{grid-template-columns:repeat(3,1fr);border-top:3px solid #7274c8;padding-top:35px}.timeline .card:before{content:'';width:19px;height:19px;border-radius:50%;background:#b1acff;position:absolute;top:-47px;left:35px}.timeline .card{min-height:235px}.footer{position:absolute;bottom:46px;left:72px;right:72px;display:flex;justify-content:space-between;font-size:20px;color:#8692b2;align-items:center}.brand{font-size:25px;letter-spacing:4px;font-weight:bold;color:#e0e4ff}.progress{position:absolute;left:0;bottom:0;height:5px;background:linear-gradient(90deg,#8581ff,#5bd4d1);border-radius:4px}#controls{position:fixed;bottom:12px;right:15px;display:flex;gap:8px;opacity:0;transition:opacity .2s}#controls:hover,#controls:focus-within{opacity:1}button{background:#252c49;color:white;border:1px solid #737a99;padding:12px 20px;border-radius:8px;cursor:pointer}.animate .card{animation:enter .55s both;animation-delay:calc(var(--i)*.1s)}@keyframes enter{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}@media(prefers-reduced-motion:reduce){.animate .card{animation:none}}
.year{display:block!important;height:470px!important;padding-top:28px}.months{display:grid;grid-template-columns:repeat(12,1fr);margin-left:200px;color:#8f9bbb;font-size:20px;text-align:center;margin-bottom:24px}.track{display:grid;grid-template-columns:200px 1fr;align-items:center;margin-bottom:32px}.track-label{font-size:25px;color:#b6bfd7}.bars{display:grid;grid-template-columns:repeat(12,1fr);gap:8px;min-height:110px;background:repeating-linear-gradient(to right,transparent 0,transparent calc(8.333% - 1px),#53608730 calc(8.333% - 1px),#53608730 8.333%);border:1px solid #50608755;border-radius:14px;padding:12px}.bar{border:1px solid #9e95ff;background:#49427c;border-radius:10px;display:flex;align-items:center;justify-content:center;font-size:25px;line-height:1.3;text-align:center;padding:10px}.bar.project{background:#174344;border-color:#5abfbb}.bar.gap{background:#171f35;border:1px dashed #697692;color:#9ca7bf;font-size:20px}.track.muted{opacity:.45}.year-note{margin-left:200px;color:#a4afc9;font-size:25px;margin-top:28px}</style><div id="stage"><main><div class="eyebrow"><span id="chapter"></span><span>FREELANCE ENGINEERING / 2026</span></div><h1 id="title"></h1><section id="content"></section><div class="footer"><span class="brand">HAMMAD</span><span id="note"></span><span id="counter"></span></div><div class="progress" id="progress"></div></main></div><nav id="controls"><button onclick="go(n-1)">← Previous</button><button onclick="go(n+1)">Next →</button><button onclick="document.documentElement.requestFullscreen()">Full screen</button></nav><script>
const slides=__SLIDES__;
const names=['Work models','Teams & buyers','Business automation','Delivery & examples','Building your practice'];let n=0;
function go(i){n=Math.max(0,Math.min(slides.length-1,i));const s=slides[n];location.hash=String(n+1);document.getElementById('chapter').textContent=String(Number(s.chapter.slice(0,2))).padStart(2,'0')+' / '+names[Number(s.chapter.slice(0,2))-1];document.getElementById('title').textContent=s.title;const content=document.getElementById('content');content.className=s.kind+(location.search.includes('still')?'':' animate');content.replaceChildren(...s.items.map((label,i)=>{const card=document.createElement('article');card.className='card';card.style.setProperty('--i',i);const num=document.createElement('div');num.className='num';num.textContent=String(i+1).padStart(2,'0');const text=document.createElement('div');text.className='label';text.textContent=label;card.append(num,text);return card}));if([4,5,27].includes(s.id)){content.className='year';const contract=s.id===27?'<div class="bar" style="grid-column:1 / 13">Main contract · agreed availability</div>':'<div class="bar" style="grid-column:1 / 7">Main contract</div><div class="bar gap" style="grid-column:7 / 10">Next engagement planning</div><div class="bar" style="grid-column:10 / 13">Next contract</div>';const projects=s.id===27?'<div class="bar project" style="grid-column:3 / 5">Small project</div><div class="bar project" style="grid-column:8 / 10">Small project</div>':'<div class="bar project" style="grid-column:1 / 3">Project A</div><div class="bar gap" style="grid-column:3 / 5">Sales & proposals</div><div class="bar project" style="grid-column:5 / 8">Project B</div><div class="bar gap" style="grid-column:8 / 10">Sales & proposals</div><div class="bar project" style="grid-column:10 / 13">Project C</div>';content.innerHTML='<div class="months">'+['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'].map(m=>'<span>'+m+'</span>').join('')+'</div><div class="track '+(s.id===5?'muted':'')+'"><div class="track-label">CONTRACT</div><div class="bars">'+contract+'</div></div><div class="track '+(s.id===4?'muted':'')+'"><div class="track-label">PROJECTS</div><div class="bars">'+projects+'</div></div><div class="year-note">'+(s.id===27?'Protect delivery time. Add projects only within agreed capacity.':'Illustrative annual schedule · include delivery and sales time.')+'</div>';}document.getElementById('counter').textContent=String(n+1).padStart(2,'0')+' / '+slides.length;document.getElementById('progress').style.width=((n+1)/slides.length*100)+'%';document.getElementById('note').textContent=s.title.startsWith('Project examples')?'Illustrative project categories':'withhammad.com';}
function resize(){document.getElementById('stage').style.transform='scale('+Math.min(innerWidth/1920,innerHeight/1080)+')'}addEventListener('resize',resize);addEventListener('keydown',e=>{if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();go(n+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(n-1)}});addEventListener('hashchange',()=>{const i=Number(location.hash.slice(1))-1;if(i!==n&&Number.isFinite(i))go(i)});resize();go(Number(location.hash.slice(1)||1)-1);window.hammadDeck={slides,go};
</script></html>'''
(P/'slides/index.html').write_text(template.replace('__SLIDES__',json.dumps([{k:v for k,v in s.items() if k not in ['narration','anchor']} for s in slides],ensure_ascii=False)))
print('Built interactive deck:',len(slides),'slides')
